message.content:
{
  "summary": "Here’s a practical checklist of what you and Mei should gather and do before submitting your first BTO application as an engaged Singapore‑Citizen couple.",
  "claims": [
    {
      "claim_id": "c1",
      "kind": "policy_fact",
      "text": "Both applicants must be Singapore Citizens to apply for a BTO flat."
    },
    {
      "claim_id": "c2",
      "kind": "policy_fact",
      "text": "First‑timer couples must not have previously owned or sold any HDB flat or received any HDB subsidy."
    },
    {
      "claim_id": "c3",
      "kind": "policy_fact",
      "text": "You need a valid HDB Flat Eligibility (HFE) letter before the ballot opens; the letter is issued after you submit the eligibility check on the HDB portal."
    },
    {
      "claim_id": "c4",
      "kind": "preparation_step",
      "text": "Create an account on the HDB Resale & BTO portal (https://services2.hdb.gov.sg) and complete the online eligibility check to obtain your HFE letter."
    },
    {
      "claim_id": "c5",
      "kind": "preparation_step",
      "text": "Gather the following documents for each applicant: NRIC (original and clear photocopy), latest income tax notice of assessment (if applicable), and recent payslips or employment letters (to confirm employment as a nurse and teacher)."
    },
    {
      "claim_id": "c6",
      "kind": "preparation_step",
      "text": "If either of you has any private property interest (e.g., a landed property or private condo), obtain the relevant ownership documents; first‑timer couples must not own any private residential property at the time of application."
    },
    {
      "claim_id": "c7",
      "kind": "preparation_step",
      "text": "Prepare a digital copy of your marriage or civil partnership certificate (or a statutory declaration of engagement) – HDB may request proof of your relationship status during the application."
    },
    {
      "claim_id": "c8",
      "kind": "preparation_step",
      "text": "Check your combined monthly household income against the current income ceiling for the BTO project you intend to apply for (usually S$14,000 for 4‑room flats); you can find the latest ceiling on the HDB website."
    },
    {
      "claim_id": "c9",
      "kind": "preparation_step",
      "text": "Decide which flat type and location you prefer, and note the ballot dates for those projects; mark the dates on your calendar so you can submit the ballot as soon as it opens."
    },
    {
      "claim_id": "c10",
      "kind": "preparation_step",
      "text": "Set up a bank account that can be used for HDB loan or CPF housing grant applications, as you will need to link it during the post‑ballot processing stage."
    },
    {
      "claim_id": "c11",
      "kind": "caveat",
      "text": "Specific document requirements and income ceilings may vary by project and are updated periodically; please verify the latest details on hdb.gov.sg or the HDB Flat Portal before you submit."
    }
  ],
  "missing_profile_fields": [],
  "profile_conflicts": [],
  "out_of_scope_reasons": []
}
